#!/usr/bin/env node
/**
 * Exports the seeded SQLite database as a portable .sql file of INSERT
 * statements, so the same demo data can be loaded on the ODU server without
 * running tsx/Prisma there (TTL-208: "npx prisma db seed fills local and
 * ODU-server databases").
 *
 *   npm run db:seed                       # fill local.db
 *   npm run db:export-sql                 # -> .db-output/seed.sql (gitignored)
 *   # on the server: sqlite3 app.db < seed.sql
 *
 * The generated file is a throwaway artefact: it lives in .db-output/ (see
 * .gitignore) and is removed by `npm run db:clean`. Nothing generated belongs in
 * the repo.
 *
 * Output is deterministic (fixed seed_* ids, stable column order, sorted rows)
 * so re-exporting produces a reviewable diff. Only rows whose id starts with
 * `seed_` — or that hang off a seeded row — are exported, so a developer's
 * scratch data never leaks into the shared file.
 *
 * Runs on plain `node` (no tsx, no Prisma client) so it also works on a Linux
 * server that only has the production dependencies installed.
 */
import 'dotenv/config';
import { createClient } from '@libsql/client';
import { writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT_DIR = resolve(ROOT, '.db-output');
const OUT_FILE = resolve(OUT_DIR, process.argv[2] ?? 'seed.sql');

if (process.argv.includes('--clean')) {
	rmSync(OUT_DIR, { recursive: true, force: true });
	console.log(`Removed ${OUT_DIR}`);
	process.exit(0);
}

const raw = process.env.DATABASE_URL;
if (!raw) {
	console.error('DATABASE_URL is not set (check .env)');
	process.exit(1);
}
// Accept "file:local.db", "./local.db", or "file:./local.db"; resolve relative to repo root.
const rel = raw.replace(/^file:/, '').replace(/^\.\//, '');
const dbPath = resolve(ROOT, rel);
const client = createClient({ url: `file:${dbPath}` });

/**
 * Tables in FK-safe order. `seedFilter` picks the rows that belong to the demo
 * dataset and `deleteWhere` is the matching DELETE, so re-applying the file is
 * idempotent.
 */
const BY_ID = (r) => String(r.id).startsWith('seed_');
// Prisma keeps camelCase column names on SQLite, so filters match that.
const BY_CAMPAIGN = (r) => String(r.campaignId).startsWith('seed_');

const TABLES = [
	{
		table: 'user',
		seedFilter: (r) => r.id === 'system' || BY_ID(r),
		deleteWhere: "id = 'system' OR id LIKE 'seed_%'"
	},
	{ table: 'account', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'verification', seedFilter: () => false, deleteWhere: null },
	{ table: 'vet_hospital', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'funding_source', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'pet', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'campaign', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'campaign_pet', seedFilter: BY_CAMPAIGN, deleteWhere: "campaignId LIKE 'seed_%'" },
	{ table: 'campaign_member', seedFilter: BY_CAMPAIGN, deleteWhere: "campaignId LIKE 'seed_%'" },
	{ table: 'campaign_image', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'donation', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'vet_record', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" },
	{ table: 'promise_to_pay', seedFilter: BY_CAMPAIGN, deleteWhere: "campaignId LIKE 'seed_%'" },
	{ table: 'campaign_review', seedFilter: BY_ID, deleteWhere: "id LIKE 'seed_%'" }
];

/** SQLite literal for a JS/SQLite value. */
function lit(value) {
	if (value === null || value === undefined) return 'NULL';
	if (typeof value === 'number') return Number.isInteger(value) ? String(value) : value.toFixed(6);
	if (typeof value === 'bigint') return value.toString();
	if (typeof value === 'boolean') return value ? '1' : '0';
	if (value instanceof Uint8Array) {
		return `X'${Array.from(value, (b) => b.toString(16).padStart(2, '0')).join('')}'`;
	}
	return `'${String(value).replaceAll("'", "''")}'`;
}

const lines = [
	'-- TakeTheLead seed data — GENERATED by prisma/export-seed-sql.mjs. Do not edit by hand.',
	'-- Regenerate with: npm run db:seed && npm run db:export-sql',
	'-- Apply with:     sqlite3 local.db < .db-output/seed.sql',
	'--                 (or: npx prisma db execute --file .db-output/seed.sql --schema prisma/schema.prisma)',
	'',
	'PRAGMA foreign_keys = OFF;',
	'BEGIN TRANSACTION;',
	''
];

let totalRows = 0;

for (const { table, seedFilter, deleteWhere } of TABLES) {
	const info = await client.execute(`PRAGMA table_info(${table})`);
	if (info.rows.length === 0) {
		console.warn(`skip  ${table} (table does not exist yet)`);
		continue;
	}
	const columns = info.rows.map((c) => String(c.name));

	const result = await client.execute(`SELECT * FROM ${table}`);
	const rows = result.rows
		.filter((r) => seedFilter(r))
		.sort((a, b) => {
			const ka = columns.map((c) => String(a[c] ?? '')).join('|');
			const kb = columns.map((c) => String(b[c] ?? '')).join('|');
			return ka.localeCompare(kb);
		});

	lines.push(`-- ---------- ${table} (${rows.length} rows) ----------`);
	// Idempotent: wipe the demo rows for this table, then re-insert.
	if (deleteWhere) lines.push(`DELETE FROM ${table} WHERE ${deleteWhere};`);

	for (const row of rows) {
		const values = columns.map((c) => lit(row[c])).join(', ');
		lines.push(
			`INSERT INTO ${table} (${columns.map((c) => `"${c}"`).join(', ')}) VALUES (${values});`
		);
	}
	totalRows += rows.length;
	lines.push('');
	console.log(`  ${String(rows.length).padStart(4)}  ${table}`);
}

lines.push('COMMIT;', 'PRAGMA foreign_keys = ON;', '');

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT_FILE, lines.join('\n'), 'utf8');
await client.close();
console.log(`\nWrote ${totalRows} rows -> ${OUT_FILE}`);
console.log('(generated artefact, gitignored — remove with: npm run db:clean)');
